-- 0001_context_primitives
-- Executed as app_migrator (see backend/tools/db/migrate.ts). Schemas "platform" and "app" and the
-- roles are created by the superuser bootstrap (backend/tools/db/bootstrap.ts), never by migrations.
--
-- Contents: UUIDv7 domain + the trusted-context accessors that every RLS policy is built from.

-- Only the runtime role may use the app schema; PUBLIC gets nothing.
REVOKE ALL ON SCHEMA app FROM PUBLIC;
GRANT USAGE ON SCHEMA app TO app_runtime;

-- Every primary key is a UUIDv7 (generated by the application, ADR-006). The domain makes the
-- database refuse anything else, including random v4 UUIDs.
CREATE DOMAIN app.uuid_v7 AS uuid
  CONSTRAINT uuid_v7_format CHECK (
    substr(VALUE::text, 15, 1) = '7'
    AND substr(VALUE::text, 20, 1) IN ('8', '9', 'a', 'b')
  );

-- Context accessors. The values come from transaction-local settings written ONLY by
-- Database.withTenant() after the application has authenticated the request. Anything missing,
-- empty or malformed yields NULL, and NULL never satisfies a policy (fail closed).
CREATE FUNCTION app.current_tenant_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE
SET search_path = pg_catalog
AS $$
  SELECT CASE
    WHEN s.v ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN s.v::uuid
  END
  FROM (SELECT lower(pg_catalog.current_setting('app.tenant_id', true)) AS v) AS s
$$;

CREATE FUNCTION app.current_user_id() RETURNS uuid
LANGUAGE sql STABLE PARALLEL SAFE
SET search_path = pg_catalog
AS $$
  SELECT CASE
    WHEN s.v ~ '^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN s.v::uuid
  END
  FROM (SELECT lower(pg_catalog.current_setting('app.user_id', true)) AS v) AS s
$$;

-- Exact, case-sensitive allowlist; any other value is "no actor".
CREATE FUNCTION app.current_actor_kind() RETURNS text
LANGUAGE sql STABLE PARALLEL SAFE
SET search_path = pg_catalog
AS $$
  SELECT CASE WHEN s.v IN ('STUDENT', 'STAFF') THEN s.v END
  FROM (SELECT pg_catalog.current_setting('app.actor_kind', true) AS v) AS s
$$;

-- Row maintenance triggers (generic, schema-wide).
CREATE FUNCTION app.touch_row() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  NEW.updated_at := pg_catalog.now();
  NEW.version := OLD.version + 1;
  RETURN NEW;
END
$$;

-- id and organization_id never change (08 §4). Moving data between tenants is never an UPDATE.
CREATE FUNCTION app.enforce_immutable_keys() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
BEGIN
  IF (pg_catalog.to_jsonb(NEW) -> 'id') IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) -> 'id')
     OR (pg_catalog.to_jsonb(NEW) -> 'organization_id') IS DISTINCT FROM (pg_catalog.to_jsonb(OLD) -> 'organization_id') THEN
    RAISE EXCEPTION 'id and organization_id are immutable' USING ERRCODE = 'restrict_violation';
  END IF;
  RETURN NEW;
END
$$;

REVOKE ALL ON FUNCTION app.current_tenant_id(), app.current_user_id(), app.current_actor_kind(),
  app.touch_row(), app.enforce_immutable_keys() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.current_tenant_id(), app.current_user_id(), app.current_actor_kind()
  TO app_runtime;
